facts=[('33.7% perovskite efficiency',['33.7','perovskite']),('29% prior',['29%']),('20% cut by 2026',['20%','2026']),('China 80%',['80%']),('IRA 50B',['50 billion','\$50']),('floating 10-15%',['10-15','floating']),('offshore fastest',['offshore']),('Dogger 3.6GW/6M homes',['3.6','6 million','Dogger']),('15MW/260m rotors',['15-megawatt','15 MW','260']),('offshore 50-60/MWh',['50-60']),('onshore 30-40/MWh',['30-40']),('150GWh/300%',['150 GWh','300%','150']),('LFP/NMC',['LFP','NMC']),('sodium-ion',['sodium']),('iron-air 100h',['iron-air','100-hour','100']),('H2 3-4/kg, 2/kg target',['3-4','2/kg']),('steel & shipping',['steel','shipping']),('500B invest',['500 billion','\$500']),('14M/40M jobs',['14 million','40 million']),('carbon 23%/15%',['23%','15%']),('CBAM',['CBAM','Carbon Border']),('permits 2-4y',['2-4']),('minerals',['mineral']),('intermittency/baseload',['intermitten','baseload']),('net-zero 2050',['2050'])]
def cov(t):
    tl=t.lower(); return [(l,any(k.lower() in tl for k in toks)) for l,toks in facts]
def rl(ref,hyp):
    rt,ht=ref.split(),hyp.split(); m,n=len(rt),len(ht)
    dp=[[0]*(n+1) for _ in range(m+1)]
    for i in range(1,m+1):
        for j in range(1,n+1):
            dp[i][j]=dp[i-1][j-1]+1 if rt[i-1]==ht[j-1] else max(dp[i-1][j],dp[i][j-1])
    lcs=dp[m][n]
    if lcs==0: return (0,0,0)
    p,r=lcs/n,lcs/m; return (2*p*r/(p+r),p,r)
print('FACT COVERAGE (of 25):')
for name,t in [('GPT-4',g),('Claude',c)]:
